<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';$username=trim((string)($_GET['username']??''));$stmt=$pdo->prepare("SELECT u.*,(SELECT COUNT(*) FROM follows WHERE creator_id=u.id) follower_count,(SELECT COUNT(*) FROM follows WHERE follower_id=u.id) following_count FROM users u WHERE u.username=? AND u.status='active'");$stmt->execute([$username]);$creator=$stmt->fetch();if(!$creator){http_response_code(404);$title='Kreator tidak ditemukan';require __DIR__.'/not-found.php';exit;}$sql='SELECT t.*,u.name author_name,u.username,u.is_verified,c.name category_name,c.icon,'.template_metrics_sql()." FROM twibbons t JOIN users u ON u.id=t.owner_id LEFT JOIN categories c ON c.id=t.category_id WHERE t.owner_id=? AND t.visibility='public' AND t.moderation_status='approved' ORDER BY t.created_at DESC";$stmt=$pdo->prepare($sql);$stmt->execute([$creator['id']]);$items=$stmt->fetchAll();$viewer=current_user();$following=false;if($viewer){$stmt=$pdo->prepare('SELECT COUNT(*) FROM follows WHERE follower_id=? AND creator_id=?');$stmt->execute([$viewer['id'],$creator['id']]);$following=(bool)$stmt->fetchColumn();}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($creator['name'])?> — Kreator Semarakin</title><meta name="description" content="Lihat karya kampanye visual dari <?=e($creator['name'])?> di Semarakin."><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><section class="creator-hero"><div class="creator-avatar"><?=e(strtoupper(mb_substr($creator['name'],0,1)))?></div><div><span class="eyebrow">@<?=e($creator['username'])?> <?=$creator['is_verified']?'· Terverifikasi':''?></span><h1><?=e($creator['name'])?></h1><p><?=e($creator['bio']?:'Kreator kampanye visual di Semarakin.')?></p><div class="creator-stats"><span><strong><?=count($items)?></strong> karya</span><span><strong><?=compact_number((int)$creator['follower_count'])?></strong> pengikut</span><span><strong><?=compact_number(array_sum(array_column($items,'use_count')))?></strong> dukungan</span></div></div><?php if($viewer&&(int)$viewer['id']!==(int)$creator['id']):?><form method="post" action="social-action"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="follow"><input type="hidden" name="creator_id" value="<?=(int)$creator['id']?>"><input type="hidden" name="return" value="creator/<?=e($creator['username'])?>"><button class="btn <?=$following?'btn-secondary':'btn-primary'?>"><?=$following?'Mengikuti':'Ikuti kreator'?></button></form><?php endif?></section><div class="section-head"><div><h2>Karya <?=e($creator['name'])?></h2><p>Koleksi publik terbaru dari kreator ini.</p></div></div><div class="social-grid"><?php foreach($items as $item):require __DIR__.'/template-card.php';endforeach?></div></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
